    "questionText": "Yozgat'ta yaşayan bir araştırmacı bulunduğu şehirden başka bir şehre gittiğinde yerel saatin daha ileri olduğunu ve gündüz süresinin daha uzun olduğunu gözlemlemiştir.\nBuna göre araştırmacının gittiği şehir ve seyahat ettiği dönem aşağıdakilerden hangisinde doğru eşleştirilmiştir?",
