    "explanation": "İzmit, Denizli, Bursa ve Gaziantep sanayi ve ticaret faaliyetlerinin yoğunluğuna bağlı olarak nüfus çeken merkezlerdir. Manisa'nın Soma ilçesinde nüfusun yoğunlaşması ise sanayi/ticaretten ziyade madencilik (linyit kömürü çıkarımı ve termik santral) fonksiyonuna dayanır.",
    "isMapQuestion": false,
