      "B": "Sultan Alparslan’ın Malazgirt Savaşı sonrasında Anadolu’nun kapılarını Türklere açması",
      "C": "Kut anlayışının İslamiyet’ten sonra Allah’ın nasibi şekline dönüşmesi",
      "D": "Tuğrul Bey’in Bağdat Seferi ile Büveyhoğulları Devleti'ne son vermesi",
