    "explanation": "Mısır, Türkler İslamiyet'i kabul etmeden çok önce, Hz. Ömer devrinde (VII. yüzyıl) fethedilerek İslamlaştırılmıştır. Türkler daha sonra Tolunoğulları, İhşidiler, Eyyubiler, Memlükler ve Osmanlılar gibi devletlerle Mısır'da hüküm sürmüş olsalar da Mısır'a İslamiyet'in yayılması Türklerin eliyle gerçekleşmemiştir. Anadolu (Selçuklular, Osmanlılar), Balkanlar (Osmanlılar), Hindistan (Gazneliler, Delhi Türk Sultanlığı, Babürler) ve Orta Asya (Karahanlılar vb.) ise Türklerin İslamiyet'i bizzat yaydığı coğrafyalardır.",
