    "explanation": "Büyük Selçuklu ve Türkiye Selçuklu devletlerinde meliklerin (şehzadelerin) eyaletlerde devlet idaresini öğrenip tecrübe kazanmalarını sağlayan eğitmen ve danışmanlara 'Atabeg' (Atabey) denirdi. Osmanlı Devleti'nde ise bu görevi 'Lala' üstlenmiştir.",
