    "questionText": "• İslam dünyasında ikinci öğretmen anlamına gelen 'muallim-i sani' ünvanıyla tanınmaktadır.\n• İhsaü'l-Ulûm adlı eserinde ilimleri sınıflandırmış, Kitabu'l-Musiki'l-Kebir adlı eserinde ise matematikle müzik arasında ilişki kurmuştur.\nSöz konusu özellikler aşağıdaki ilim insanlarından hangisine aittir?",
