    "questionText": "1090 yılında erişilmesi çok zor olan Alamut Kalesi’ni ele geçirip burada yetiştirdiği fedaileri ile Bâtınilik propagandası yaparak birçok din ve devlet adamını kendine has yöntemler ile ortadan kaldırtan kişi kimdir?",
