    "markedAnswer": "C",
    "correctAnswer": "C",
    "explanation": "Harita incelendiğinde Osmanlı Beyliği'nin güneyinde Germiyanoğulları yer aldığı için sınır komşusudur (I). Anadolu topraklarında Bizans hakimiyeti kalmamış, tüm Anadolu Türk beylikleri ve devletleri arasında paylaşılmıştır (II). Osmanlı Devleti henüz Rumeli tarafına geçmemiştir (III). Bu nedenle I ve II (C seçeneği) doğrudur.",
    "isMapQuestion": true,
