    "explanation": "Açıklamalarda Çaka Beyliği (İzmir), Mengücekliler (Divriği), Saltuklular (Erzurum, Mama Hatun) ve Artuklular (Hasankeyf/Malabadi) hakkında bilgi verilmiştir. Sivas/Tokat merkezli Danişmentliler hakkında bilgi verilmemiştir.",
    "isMapQuestion": false,
