    "questionText": "Osmanlı Devleti'nde idari birimler arasındaki haberleşmeyi sağlamak ve fermanları istenilen yerlere zamanında ulaştırmak için, ana yolların geçtiği şehir ve kasabalarda uygun aralıklarla yapılan durak yerleri aşağıdakilerden hangisiyle adlandırılmıştır?",
