    "explanation": "Osmanlı Devleti'nde ana yollar üzerindeki posta, kurye, haberleşme ve resmî taşımacılık hizmetlerini yürüten konaklama/durak noktalarına 'Menzil' veya 'Menzil Teşkilatı' denir. Kahhâl göz hekimi, Tahrir sayım ve vergi tescili, Tereke miras kaydı, Ehl-i Hirfet ise loncalara bağlı sanatkâr ve zanaatkârlardır.",
