    "questionText": "Osmanlı Devleti'nde Müslümanlar için şer'i mahkemeler, gayrimüslimler için cemaat mahkemeleri, yabancı devlet vatandaşları için ise konsolosluk mahkemeleri bulunmaktaydı.\nBu durum Osmanlı Devleti ile ilgili aşağıdakilerden hangisinin göstergesidir?",
