    "questionText": "Osmanlı Devleti'nde tarım arazileri devletin mülkiyetindedir. Toprakların kiracısı konumunda olan çiftçilerin temel görevi toprakları işlemek ve devlete vergi ödemektir. Topraklarını ekmeyen çiftçilerden çiftbozan vergisi alınmıştır.\nOsmanlı Devleti'ndeki bu durumun;\nI. üretim faaliyetlerinde sürekliliğin sağlanması,\nII. toplumda dikey hareketliliğin artması,\nIII. büyük arazi sahiplerinin ortaya çıkmasının engellenmesi\ngelişmelerinden hangilerine ortam hazırlaması beklenebilir?",
