    "topic": "Osmanlı Devleti / Lale Devri Islahatları",
    "questionText": "Lale Devri’nde yapılan yeniliklerden bazıları şunlardır:\n• Tercüme ve bilim heyetleri oluşturulmuştur.\n• İlk kez çiçek aşısı uygulanmıştır.\n• Tulumbacı Ocağı oluşturulmuştur.\n• İlk Türk matbaası kurulmuştur.\n\nBuna göre Lale Devri ile ilgili aşağıdakilerden hangisine ulaşılamaz?",
