    "questionText": "Osmanlı Devleti'nde modern anlamda faaliyet gösteren ilk sosyal yardım kurumu olup günümüzde de varlığını sürdüren, II. Abdülhamit Dönemi'nde İstanbul'da açılan kurum aşağıdakilerden hangisidir?",
