    "questionText": "9. Osmanlı Devleti XVI. yüzyılda başta Akdeniz olmak üzere birçok denizde egemenlik kurmuşken, XVII. yüzyılda bu egemenliğin zayıfladığı görülmektedir. Osmanlı Devleti'nin denizlerdeki egemenliğinin zayıflamasında aşağıdakilerden hangisinin etkisi yoktur?",
