    "questionText": "Atatürk;\n\n“Bize milliyetperver derler. Fakat biz öyle milliyetperverleriz ki bizimle iş birliği eden bütün milletlere hürmet ve riayet ederiz. Onların bütün milliyetlerinin icabatını tanırız. Bizim milliyetperverliğimiz herhâlde bencil ve mağrurane bir milliyetperverlik değildir.”\n\n“Diyarbakırlı, Vanlı, Erzurumlu, Trabzonlu, İstanbullu, Trakyalı ve Makedonyalı hep bir ırkın evlatları, hep aynı cevherin damarlarıdır.”\n\nsözleri ile Türk milliyetçiliğinin;\n\nI. ırkçılığı reddettiği,\nII. birleştirici ve bütünleştirici olduğu,\nIII. diğer milletlerin bağımsızlığına saygı duyduğu\n\nözelliklerinden hangilerine sahip olduğunu vurgulamıştır?",
    "options": {
      "A": "Yalnız I",
      "B": "I ve II",
      "C": "I ve III",
      "D": "II ve III",
      "E": "I, II ve III"
    },
    "markedAnswer": "C",
    "correctAnswer": "E",
    "explanation": "Atatürk'ün sözlerinde diğer milletlere saygı duyulması (III), bencil ve mağrur olunmaması/barışçıl yaklaşım ile ayrım gözetmeksizin millet tanımı yapılması ırkçılığı reddetmesi (I) ve yurdun dört bir yanındaki insanları aynı cevher olarak nitelendirmesi birleştirici/bütünleştirici olduğunu (II) gösterir.",
    "isMapQuestion": false,
