    "questionText": "XIX. yüzyılda Avusturya ve Rusya'nın tehdidine karşılık, Osmanlı Devleti'nin Macar ve Leh mültecileri geri vermemesi aşağıdaki savaşlardan hangisine neden olmuştur?",
