    "questionText": "13. Osmanlı Devleti I. Balkan Savaşı'nda, Balkan devletlerine mağlup olmuş ve Midye-Enez hattının batısındaki bütün topraklarını kaybetmiştir.\n\nBuna göre Osmanlı Devleti'nin Balkan Savaşlarında başarısız olmasında aşağıdakilerden hangisi etkili olmamıştır?",
