    "explanation": "I. Balkan Savaşı'nda Osmanlı Devleti'nin yenilmesinde orduda particilik (İttihatçı-İtilafçı subay çekişmesi), savaş öncesi tecrübeli askerlerin terhis edilmiş olması, savaşa hazırlıksız girilmesi ve dört devlete karşı aynı anda mücadele edilmesi etkili olmuştur. Balkan devletleri arasındaki Kiliseler Sorunu'nun 1910 yılında çıkarılan kanunla çözülmesi ise Balkan devletlerinin aralarındaki ihtilafı sona erdirerek Osmanlı'ya karşı ittifak kurabilmelerine zemin hazırlamıştır. Dolayısıyla kiliseler sorununun çıkması yenilgiye neden olmamıştır.",
    "isMapQuestion": false,
