    "questionText": "15. I. Dünya Savaşı'ndan sonra Almanya, Avusturya-Macaristan, Osmanlı ve Çarlık Rusya imparatorlukları parçalanmıştır. Bunların yerine Avrupa'da birçok yeni devlet kurulmuş, Avrupa'nın siyasi haritası değişmiştir.\n\nBuna göre aşağıdakilerden hangisi bu yeni devletlerden birisi değildir?",
