    "correctAnswer": "D",
    "explanation": "II. TBMM dönemi 11 Ağustos 1923 ile 1 Ekim 1927 tarihleri arasını kapsar. Halifeliğin kaldırılması (1924), Tevhid-i Tedrisat Kanunu (1924), Terakkiperver Cumhuriyet Fırkası'nın kuruluşu (1924) ve Türk Medeni Kanunu'nun kabulü (1926) II. TBMM dönemindedir. I. Beş Yıllık Sanayi Planı ise 1933 yılında hazırlanarak 1934'te IV. TBMM döneminde uygulanmaya başlanmıştır.",
