    "questionText": "Devlet yönetiminin kişilere veya belirli bir toplumsal zümreye değil, doğrudan millete ait olması \"milli egemenlik\" olarak tanımlanmaktadır.\nBuna göre milli egemenlik kavramı aşağıdaki Atatürk ilkelerinden hangisiyle daha yakından ilgilidir?",
