    "topic": "Çağdaş Türk ve Dünya Tarihi",
    "questionText": "Azerbaycan'ın milli direnişinin simge isimlerinden birisidir. Müsavat Partisi'nin liderliğini yapmıştır. Azerbaycan Millî Şûrası'nın başkanı olarak 1918'de Azerbaycan Halk Cumhuriyeti'nin bağımsızlığını ilan etmiştir.\n\nSöz konusu özellikler aşağıdaki devlet adamlarından hangisine aittir?",
