    "explanation": "28 Mayıs 1918'de kurulan ilk demokratik Türk cumhuriyeti olan Azerbaycan Halk Cumhuriyeti'nin kurucusu, Millî Şûra başkanı ve Müsavat Partisi'nin lideri Mehmet Emin Resulzade'dir. Kendisi 'Bir kere yükselen bayrak, bir daha inmez!' vecizesiyle de tanınır.",
    "isMapQuestion": false,
