    "questionText": "NATO ittifakına katılan Türkiye hem siyasî güvene kavuşmuş hem de askerî alanda yardım almıştır. NATO sayesinde Türk ordusu modern araç ve silahlara sahip olmuştur.\n\nBu durum Türkiye'nin aşağıdaki devletlerden hangisiyle olan ilişkilerini olumsuz yönde etkilemiştir?",
