    "explanation": "Türkiye'nin 1952 yılında Kuzey Atlantik Antlaşması Örgütü'ne (NATO) üye olması, Batı İttifakı'nın karşı kutbu olan Doğu Bloku lideri SSCB ile olan ilişkilerini olumsuz yönde etkilemiş ve Soğuk Savaş dönemindeki kutuplaşmayı artırmıştır.",
    "isMapQuestion": false,
